func (h Handle) Zlaswp(n int32, a driver.DevicePtr, lda int32, k1 int32, k2 int32, devIpiv driver.DevicePtr, incx int32) error {
	return zlaswp(h, n, a, lda, k1, k2, devIpiv, incx)
}

